SELECT * FROM ( SELECT TASK_ID AS taskId, AGENT_ID AS agentId, TASK_TYPE AS taskType, TASK_AREA AS taskArea, TASK_TITLE AS taskTitle, TASK_CONTENT AS taskContent, ACTION_STATUS AS actionStatus, START_TIME AS startTime, END_TIME AS endTime, TASK_NOTE AS taskNote, REG_DATE AS regDate, ROWNUM AS RNUM FROM ( SELECT TASK_ID, AGENT_ID, TASK_TYPE, TASK_AREA, TASK_TITLE, TASK_CONTENT, ACTION_STATUS, START_TIME, END_TIME, TASK_NOTE, REG_DATE FROM AGENT_TASK
AND TASK_AREA = #{taskArea}
AND TASK_TYPE = #{taskType}
AND (TASK_TITLE LIKE '%' || #{keyword} || '%' OR TASK_CONTENT LIKE '%' || #{keyword} || '%')
AND START_TIME >= REPLACE(#{startDate}, '.', '-') AND START_TIME <= REPLACE(#{endDate}, '.', '-') || ' 23:59:59'
ORDER BY TASK_ID DESC ) A WHERE ROWNUM <= #{offset} + #{limit} ) WHERE RNUM > #{offset}

SELECT COUNT(*) FROM AGENT_TASK
AND TASK_AREA = #{taskArea}
AND TASK_TYPE = #{taskType}
AND (TASK_TITLE LIKE '%' || #{keyword} || '%' OR TASK_CONTENT LIKE '%' || #{keyword} || '%')
AND START_TIME >= REPLACE(#{startDate}, '.', '-') AND START_TIME <= REPLACE(#{endDate}, '.', '-') || ' 23:59:59'
